namespace Challenge;public record Product(string Id,string Name);public record View(string Id,string Name,int Stock);public sealed class CatalogRepository(List<Product> products,Dictionary<string,int> stock){public int QueryCount;public IReadOnlyList<Product> Products(int skip,int take){QueryCount++;return products.Skip(skip).Take(take).ToList();}public int Stock(string id){QueryCount++;return stock.GetValueOrDefault(id);}public IReadOnlyDictionary<string,int> Stocks(IEnumerable<string> ids){QueryCount++;return ids.ToDictionary(x=>x,x=>stock.GetValueOrDefault(x));}public void Set(string id,int n)=>stock[id]=n;}
public sealed class CatalogService(CatalogRepository repo){public IReadOnlyList<View> List(int skip,int take){var products=repo.Products(skip,take);var stocks=repo.Stocks(products.Select(x=>x.Id));return products.Select(x=>new View(x.Id,x.Name,stocks.GetValueOrDefault(x.Id))).ToList();}}
